"""Generated by AetherLab - kinetic theory (curated component)."""

import numpy as np
from manim import *


class AetherLabScene(Scene):
    def construct(self):
        xmax, ymax = 3.1, 2.1
        data = [[-0.8441, -0.5997, 0.8366, 0.7016], [-1.8858, -1.8134, 0.0886, 0.7112], [-0.741, 1.1719, 0.4848, 1.2308], [2.7217, 1.216, 0.2398, 2.6614], [2.0567, -0.0317, -1.2616, -1.3385], [1.0068, -1.1485, 0.6667, -0.1711], [2.8877, -0.6701, 1.18, -0.0174], [1.4117, -0.4806, -1.5312, 0.4743], [-1.1315, -1.1058, -1.3249, 0.2763], [-0.7176, -1.8529, 0.1032, 0.3178], [2.4644, -1.6403, -1.2311, 2.2959], [-1.2224, 1.7386, 0.4387, -0.805], [2.1356, -0.9262, 1.9288, -1.9564], [-0.748, -0.6245, 0.242, 0.5017], [-2.3412, -0.5537, -1.0787, -1.7462], [-1.6848, -1.757, -0.0315, -1.6034], [-0.0776, -0.6124, 0.6764, 0.96], [-0.0349, 0.2801, -0.6997, -0.0881], [0.9983, -1.428, -0.1168, -0.5775], [-1.2033, -0.7442, 0.1628, 0.2876], [1.4878, -0.074, 1.6077, 0.3398], [-1.7147, -1.7302, -1.0877, -1.028]]

        title = Text('Kinetic theory of an ideal gas').scale(0.44).to_edge(UP)
        box = Rectangle(width=2 * xmax, height=2 * ymax, color=GREY_A, stroke_width=3)
        box.shift(LEFT * 2.0)
        offset = box.get_center()

        particles = VGroup()
        for px, py, vx, vy in data:
            dot = Dot(offset + np.array([px, py, 0.0]), color=TEAL, radius=0.08)
            dot.velocity = np.array([vx, vy, 0.0])
            particles.add(dot)

        def step(mob, dt):
            dt = min(dt, 0.05)
            for d in mob:
                d.shift(d.velocity * dt)
                local = d.get_center() - offset
                if abs(local[0]) > xmax:
                    d.velocity[0] *= -1
                    d.shift(np.array([np.sign(local[0]) * (xmax - abs(local[0])), 0, 0]))
                if abs(local[1]) > ymax:
                    d.velocity[1] *= -1
                    d.shift(np.array([0, np.sign(local[1]) * (ymax - abs(local[1])), 0]))

        # The 2D Maxwell (Rayleigh) speed density matches Gaussian vx and vy.
        sigma = 1.1
        speed_max = 4.0
        axes = Axes(
            x_range=[0, speed_max, speed_max / 4], y_range=[0, 1.1, 0.5],
            x_length=3.6, y_length=2.6,
            axis_config={"include_tip": False, "stroke_opacity": 0.5},
        ).to_corner(DR, buff=0.6)
        density = axes.plot(
            lambda v: (v / (sigma * sigma)) * np.exp(-(v * v) / (2 * sigma * sigma)),
            x_range=[0.01, speed_max], color=GOLD,
        )
        mb_label = Text("2D Maxwell speed density").scale(0.3).next_to(axes, UP, buff=0.12)

        self.play(FadeIn(title), Create(box), run_time=0.9)
        self.play(LaggedStart(*[GrowFromCenter(d) for d in particles], lag_ratio=0.02),
                  run_time=1.2)
        self.play(Create(axes), Create(density), FadeIn(mb_label), run_time=1.0)
        particles.add_updater(step)
        self.wait(5.5)
        particles.remove_updater(step)
        self.wait(0.3)
